//go:build amd64 && !purego
// +build amd64,!purego

#include "textflag.h"

#define LOAD_BE_WORD(OFF, STK) \
	MOVL	OFF(SI), AX; \
	BSWAPL	AX; \
	MOVL	AX, STK(SP)

#define STORE_BE_WORD(STK, OFF) \
	MOVL	STK(SP), AX; \
	BSWAPL	AX; \
	MOVL	AX, OFF(DI)

#define SBOX_POS(SBOX, POSMASK, NIBS, ACC, TMP) \
	VPSHUFB	NIBS, SBOX, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SBOX_POS_HI(SBOX, POSMASK, NIBS, ACC, TMP) \
	VPSHUFB	NIBS, SBOX, TMP; \
	VPSLLW	$4, TMP, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SBOX_POS_LOAD(SBOX, POSMASK, NIBS, ACC, TMP) \
	VMOVDQU	SBOX(SB), TMP; \
	VPSHUFB	NIBS, TMP, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SBOX_POS_HI_LOAD(SBOX, POSMASK, NIBS, ACC, TMP) \
	VMOVDQU	SBOX(SB), TMP; \
	VPSHUFB	NIBS, TMP, TMP; \
	VPSLLW	$4, TMP, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SUBST_LOAD(IN, OUT, LOW, HIGH, TMP) \
	VMOVDQU	IN, LOW; \
	VPAND	Y15, LOW, LOW; \
	VMOVDQU	IN, HIGH; \
	VPSRLW	$4, HIGH, HIGH; \
	VPAND	Y15, HIGH, HIGH; \
	VPXOR	OUT, OUT, OUT; \
	SBOX_POS_LOAD(·magmaSIMDSbox+0, ·magmaSIMDPos0Mask, LOW, OUT, TMP); \
	SBOX_POS_LOAD(·magmaSIMDSbox+64, ·magmaSIMDPos1Mask, LOW, OUT, TMP); \
	SBOX_POS_LOAD(·magmaSIMDSbox+128, ·magmaSIMDPos2Mask, LOW, OUT, TMP); \
	SBOX_POS_LOAD(·magmaSIMDSbox+192, ·magmaSIMDPos3Mask, LOW, OUT, TMP); \
	SBOX_POS_HI_LOAD(·magmaSIMDSbox+32, ·magmaSIMDPos0Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI_LOAD(·magmaSIMDSbox+96, ·magmaSIMDPos1Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI_LOAD(·magmaSIMDSbox+160, ·magmaSIMDPos2Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI_LOAD(·magmaSIMDSbox+224, ·magmaSIMDPos3Mask, HIGH, OUT, TMP)

#define SUBST(IN, OUT, LOW, HIGH, TMP) \
	VMOVDQU	IN, LOW; \
	VPAND	Y15, LOW, LOW; \
	VMOVDQU	IN, HIGH; \
	VPSRLW	$4, HIGH, HIGH; \
	VPAND	Y15, HIGH, HIGH; \
	VPXOR	OUT, OUT, OUT; \
	SBOX_POS(Y7, ·magmaSIMDPos0Mask, LOW, OUT, TMP); \
	SBOX_POS(Y9, ·magmaSIMDPos1Mask, LOW, OUT, TMP); \
	SBOX_POS(Y11, ·magmaSIMDPos2Mask, LOW, OUT, TMP); \
	SBOX_POS(Y13, ·magmaSIMDPos3Mask, LOW, OUT, TMP); \
	SBOX_POS_HI(Y8, ·magmaSIMDPos0Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y10, ·magmaSIMDPos1Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y12, ·magmaSIMDPos2Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y14, ·magmaSIMDPos3Mask, HIGH, OUT, TMP)

TEXT ·cpuid(SB), NOSPLIT, $0-24
	MOVL	eaxArg+0(FP), AX
	MOVL	ecxArg+4(FP), CX
	CPUID
	MOVL	AX, eax+8(FP)
	MOVL	BX, ebx+12(FP)
	MOVL	CX, ecx+16(FP)
	MOVL	DX, edx+20(FP)
	RET

TEXT ·xgetbv(SB), NOSPLIT, $0-16
	MOVL	index+0(FP), CX
	XGETBV
	MOVL	AX, eax+8(FP)
	MOVL	DX, edx+12(FP)
	RET

TEXT ·cryptBlocksAVX2(SB), NOSPLIT, $64-32
	MOVQ	dst+0(FP), DI
	MOVQ	src+8(FP), SI
	MOVQ	n+16(FP), R12
	MOVQ	keys+24(FP), R8
	VMOVDQU	·magmaSIMDNibbleMask(SB), Y15
	VMOVDQU	·magmaSIMDSbox+0(SB), Y7
	VMOVDQU	·magmaSIMDSbox+32(SB), Y8
	VMOVDQU	·magmaSIMDSbox+64(SB), Y9
	VMOVDQU	·magmaSIMDSbox+96(SB), Y10
	VMOVDQU	·magmaSIMDSbox+128(SB), Y11
	VMOVDQU	·magmaSIMDSbox+160(SB), Y12
	VMOVDQU	·magmaSIMDSbox+192(SB), Y13
	VMOVDQU	·magmaSIMDSbox+224(SB), Y14

avx2Loop:
	VMOVDQU	0(SI), Y2
	VMOVDQU	32(SI), Y3
	VPSHUFB	·magmaByteSwap32(SB), Y2, Y2
	VPSHUFB	·magmaByteSwap32(SB), Y3, Y3
	VMOVDQU	·magmaSIMDPermN1(SB), Y4
	VMOVDQU	·magmaSIMDPermN2(SB), Y5
	VPERMD	Y2, Y4, Y0
	VPERMD	Y3, Y4, Y6
	VPERM2I128	$0x20, Y6, Y0, Y0
	VPERMD	Y2, Y5, Y1
	VPERMD	Y3, Y5, Y6
	VPERM2I128	$0x20, Y6, Y1, Y1
	MOVQ	R8, R9
	MOVQ	$32, R10

avx2Round:
	VPBROADCASTD	(R9), Y2
	VPADDD	Y2, Y0, Y3
	SUBST(Y3, Y4, Y5, Y6, Y2)
	VPSLLD	$11, Y4, Y5
	VPSRLD	$21, Y4, Y4
	VPOR	Y5, Y4, Y4
	VPXOR	Y1, Y4, Y4
	VMOVDQU	Y0, Y1
	VMOVDQU	Y4, Y0
	ADDQ	$4, R9
	SUBQ	$1, R10
	JNZ	avx2Round

	VPSHUFB	·magmaByteSwap32(SB), Y0, Y0
	VPSHUFB	·magmaByteSwap32(SB), Y1, Y1
	VPUNPCKLDQ	Y1, Y0, Y2
	VPUNPCKHDQ	Y1, Y0, Y3
	VPERM2I128	$0x20, Y3, Y2, Y4
	VPERM2I128	$0x31, Y3, Y2, Y5
	VMOVDQU	Y4, 0(DI)
	VMOVDQU	Y5, 32(DI)

	ADDQ	$64, SI
	ADDQ	$64, DI
	SUBQ	$64, R12
	JNZ	avx2Loop
	VZEROUPPER
	RET

TEXT ·cryptBlocksAVX2x16(SB), NOSPLIT, $0-32
	MOVQ	dst+0(FP), DI
	MOVQ	src+8(FP), SI
	MOVQ	n+16(FP), R12
	MOVQ	keys+24(FP), R8
	VMOVDQU	·magmaSIMDNibbleMask(SB), Y15
	VMOVDQU	·magmaSIMDPermN1(SB), Y9
	VMOVDQU	·magmaSIMDPermN2(SB), Y10

avx2x16Loop:
	VMOVDQU	0(SI), Y0
	VMOVDQU	32(SI), Y1
	VPSHUFB	·magmaByteSwap32(SB), Y0, Y0
	VPSHUFB	·magmaByteSwap32(SB), Y1, Y1
	VPERMD	Y0, Y9, Y4
	VPERMD	Y1, Y9, Y5
	VPERM2I128	$0x20, Y5, Y4, Y4
	VPERMD	Y0, Y10, Y6
	VPERMD	Y1, Y10, Y7
	VPERM2I128	$0x20, Y7, Y6, Y6
	VMOVDQU	Y4, Y0
	VMOVDQU	Y6, Y1

	VMOVDQU	64(SI), Y2
	VMOVDQU	96(SI), Y3
	VPSHUFB	·magmaByteSwap32(SB), Y2, Y2
	VPSHUFB	·magmaByteSwap32(SB), Y3, Y3
	VPERMD	Y2, Y9, Y4
	VPERMD	Y3, Y9, Y5
	VPERM2I128	$0x20, Y5, Y4, Y4
	VPERMD	Y2, Y10, Y6
	VPERMD	Y3, Y10, Y7
	VPERM2I128	$0x20, Y7, Y6, Y6
	VMOVDQU	Y4, Y2
	VMOVDQU	Y6, Y3

	MOVQ	R8, R9
	MOVQ	$32, R10

avx2x16Round:
	VPBROADCASTD	(R9), Y8

	VPADDD	Y8, Y0, Y4
	SUBST_LOAD(Y4, Y7, Y5, Y6, Y4)
	VPSLLD	$11, Y7, Y5
	VPSRLD	$21, Y7, Y7
	VPOR	Y5, Y7, Y7
	VPXOR	Y1, Y7, Y7
	VMOVDQU	Y0, Y1
	VMOVDQU	Y7, Y0

	VPADDD	Y8, Y2, Y4
	SUBST_LOAD(Y4, Y7, Y5, Y6, Y4)
	VPSLLD	$11, Y7, Y5
	VPSRLD	$21, Y7, Y7
	VPOR	Y5, Y7, Y7
	VPXOR	Y3, Y7, Y7
	VMOVDQU	Y2, Y3
	VMOVDQU	Y7, Y2

	ADDQ	$4, R9
	SUBQ	$1, R10
	JNZ	avx2x16Round

	VPSHUFB	·magmaByteSwap32(SB), Y0, Y0
	VPSHUFB	·magmaByteSwap32(SB), Y1, Y1
	VPUNPCKLDQ	Y1, Y0, Y4
	VPUNPCKHDQ	Y1, Y0, Y5
	VPERM2I128	$0x20, Y5, Y4, Y6
	VPERM2I128	$0x31, Y5, Y4, Y7
	VMOVDQU	Y6, 0(DI)
	VMOVDQU	Y7, 32(DI)

	VPSHUFB	·magmaByteSwap32(SB), Y2, Y2
	VPSHUFB	·magmaByteSwap32(SB), Y3, Y3
	VPUNPCKLDQ	Y3, Y2, Y4
	VPUNPCKHDQ	Y3, Y2, Y5
	VPERM2I128	$0x20, Y5, Y4, Y6
	VPERM2I128	$0x31, Y5, Y4, Y7
	VMOVDQU	Y6, 64(DI)
	VMOVDQU	Y7, 96(DI)

	ADDQ	$128, SI
	ADDQ	$128, DI
	SUBQ	$128, R12
	JNZ	avx2x16Loop
	VZEROUPPER
	RET

TEXT ·xorKeyStreamCTRAVX2(SB), NOSPLIT, $8-44
	MOVQ	dst+0(FP), DI
	MOVQ	src+8(FP), SI
	MOVQ	n+16(FP), R12
	MOVQ	keys+24(FP), R8
	MOVL	left+32(FP), AX
	MOVL	right+36(FP), BX
	VMOVDQU	·magmaSIMDNibbleMask(SB), Y15
	VMOVDQU	·magmaSIMDSbox+0(SB), Y7
	VMOVDQU	·magmaSIMDSbox+32(SB), Y8
	VMOVDQU	·magmaSIMDSbox+64(SB), Y9
	VMOVDQU	·magmaSIMDSbox+96(SB), Y10
	VMOVDQU	·magmaSIMDSbox+128(SB), Y11
	VMOVDQU	·magmaSIMDSbox+160(SB), Y12
	VMOVDQU	·magmaSIMDSbox+192(SB), Y13
	VMOVDQU	·magmaSIMDSbox+224(SB), Y14

avx2CTRLoop:
	MOVL	BX, 0(SP)
	VPBROADCASTD	0(SP), Y0
	VPADDD	·magmaCTRRightInc(SB), Y0, Y0
	MOVL	AX, 0(SP)
	VPBROADCASTD	0(SP), Y1
	MOVQ	R8, R9
	MOVQ	$32, R10

avx2CTRRound:
	VPBROADCASTD	(R9), Y2
	VPADDD	Y2, Y0, Y3
	SUBST(Y3, Y4, Y5, Y6, Y2)
	VPSLLD	$11, Y4, Y5
	VPSRLD	$21, Y4, Y4
	VPOR	Y5, Y4, Y4
	VPXOR	Y1, Y4, Y4
	VMOVDQU	Y0, Y1
	VMOVDQU	Y4, Y0
	ADDQ	$4, R9
	SUBQ	$1, R10
	JNZ	avx2CTRRound

	VPSHUFB	·magmaByteSwap32(SB), Y0, Y0
	VPSHUFB	·magmaByteSwap32(SB), Y1, Y1
	VPUNPCKLDQ	Y1, Y0, Y2
	VPUNPCKHDQ	Y1, Y0, Y3
	VPERM2I128	$0x20, Y3, Y2, Y4
	VPERM2I128	$0x31, Y3, Y2, Y5
	VPXOR	0(SI), Y4, Y4
	VPXOR	32(SI), Y5, Y5
	VMOVDQU	Y4, 0(DI)
	VMOVDQU	Y5, 32(DI)

	ADDQ	$64, SI
	ADDQ	$64, DI
	ADDL	$8, BX
	SUBQ	$64, R12
	JNZ	avx2CTRLoop
	MOVL	BX, ret+40(FP)
	VZEROUPPER
	RET
